package federationconfig

// OIDCConfigurationHTML is the shared OpenID Connect setup section used by app templates.
const OIDCConfigurationHTML = `{{with .OIDC}}<section class="wide" id="integrations.oidc"><h2>Single sign-on</h2><p class="oidc-intro">Use a standards-based OpenID Connect provider. Create a confidential web application. Your return address is your Kinosail HTTPS address followed by <code>/login/oidc/callback</code>. Register it exactly with the provider.</p>{{if .Control.Managed}}<p>Single sign-on is configured outside Kinosail. Update all five values together and restart Kinosail Server.</p>{{range .Control.DockerVars}}<p>Configured via Docker: <code>{{.}}</code>.</p>{{end}}{{range .Control.YAMLKeys}}<p>Configured via YAML: <code>{{.}}</code>.</p>{{end}}{{else}}<p>{{if .Configured}}Single sign-on is configured.{{else}}Single sign-on is not configured.{{end}}</p><form action="/settings/configuration" method="post"><input type="hidden" name="key" value="integrations.oidc"><div class="oidc-fields"><label>Return address<input aria-label="Single sign-on return address" name="redirectUrl" type="url" value="{{.RedirectURL}}" placeholder="https://media.example.com/login/oidc/callback" maxlength="2048" autocomplete="url" spellcheck="false" required></label><label>Issuer URL<input aria-label="Single sign-on issuer" name="issuer" type="url" value="{{.Issuer}}" placeholder="https://identity.example.com" maxlength="2048" autocomplete="url" spellcheck="false" required></label><label>Client ID<input aria-label="Single sign-on client ID" name="clientId" value="{{.ClientID}}" maxlength="512" autocomplete="off" spellcheck="false" required></label><label>Client secret<input aria-label="Single sign-on client secret" name="clientSecret" type="password" maxlength="4096" autocomplete="new-password" placeholder="{{if .SecretConfigured}}Leave blank to keep the configured secret{{else}}Client secret{{end}}" {{if not .SecretConfigured}}required{{end}}></label></div><label>Identity claim<input aria-label="Single sign-on identity claim" name="identityClaim" value="{{.IdentityClaim}}" placeholder="sub" maxlength="256" autocomplete="off" spellcheck="false" required></label><p>Provision the same claim value as the SCIM <code>externalId</code>. Keep <code>sub</code> unless your provider uses another stable claim, such as Microsoft Entra <code>oid</code>.</p><button>Save single sign-on</button><p>Applies after a restart.</p></form>{{if .Configured}}<form action="/settings/configuration/reset" method="post"><button class="quiet" name="key" value="integrations.oidc">Disable single sign-on</button></form>{{end}}{{end}}<details><summary>Technical details</summary><p>Configuration keys: <code>integrations.oidc.issuer</code>, <code>integrations.oidc.client_id</code>, <code>integrations.oidc.client_secret</code>, <code>integrations.oidc.redirect_url</code>, <code>integrations.oidc.identity_claim</code>.</p></details></section>{{end}}`

// SAMLConfigurationHTML is the shared SAML setup section used by app templates.
const SAMLConfigurationHTML = `{{with .SAML}}<section class="wide integration-setup" id="integrations.saml"><h2>SAML single sign-on</h2><p>Connect a Security Assertion Markup Language (SAML) 2.0 identity provider. Use its metadata URL, or paste a downloaded metadata document.</p><div class="scim-endpoint"><div class="copy-field"><label>Service provider metadata<input id="saml-sp-metadata" value="{{.SPMetadataURL}}" readonly spellcheck="false"></label><button class="quiet" type="button" aria-label="Copy service provider metadata URL" data-copy-target="saml-sp-metadata">Copy URL</button><span class="copy-status" aria-live="polite"></span></div><div class="copy-field"><label>Assertion Consumer Service URL<input id="saml-acs-url" value="{{.ACSURL}}" readonly spellcheck="false"></label><button class="quiet" type="button" aria-label="Copy Assertion Consumer Service URL" data-copy-target="saml-acs-url">Copy URL</button><span class="copy-status" aria-live="polite"></span></div></div><p>{{if .Configured}}SAML single sign-on is configured.{{else}}SAML single sign-on is not configured.{{end}}</p>{{if .Control.Managed}}<p>SAML is configured outside Kinosail. Update the metadata source and identity attribute together, then restart Kinosail Server.</p>{{range .Control.DockerVars}}<p>Configured via Docker: <code>{{.}}</code>.</p>{{end}}{{range .Control.YAMLKeys}}<p>Configured via YAML: <code>{{.}}</code>.</p>{{end}}{{else}}<form action="/settings/configuration" method="post"><input type="hidden" name="key" value="integrations.saml"><label>Provider metadata URL<input aria-label="SAML provider metadata URL" name="metadataUrl" type="url" value="{{.ProviderMetadataURL}}" placeholder="https://identity.example/application/metadata" maxlength="2048" autocomplete="url" spellcheck="false"></label><p>Or use a downloaded metadata document.</p><label>Provider metadata XML<textarea aria-label="SAML provider metadata XML" name="metadataXml" rows="6" maxlength="262144" spellcheck="false">{{.ProviderMetadataXML}}</textarea></label><label>Identity attribute<input aria-label="SAML identity attribute" name="identityAttribute" value="{{.IdentityAttribute}}" placeholder="NameID" maxlength="256" autocomplete="off" spellcheck="false" required></label><p>Provision the same value as the SCIM <code>externalId</code>. Keep <code>NameID</code>, or enter one signed assertion attribute name.</p><button>Save SAML</button><p>Enter exactly one metadata source. Changes apply after a restart.</p></form>{{if .Configured}}<form action="/settings/configuration/reset" method="post"><button class="quiet" name="key" value="integrations.saml">Disable SAML</button></form>{{end}}{{end}}<details><summary>Technical details</summary><p>Entity ID: <code>{{.SPMetadataURL}}</code></p><p>Metadata URL certificates refresh every hour. Configuration keys: <code>integrations.saml.metadata_url</code>, <code>integrations.saml.metadata_xml</code>, <code>integrations.saml.identity_attribute</code>.</p></details></section>{{end}}`
